126: static int get_timer_irq(void)
127: {
128: 	struct irq_domain *d = irq_find_matching_fwnode(cpuintc_handle, DOMAIN_BUS_ANY);
129: 
130: 	if (d)
131: 		return irq_create_mapping(d, EXCCODE_TIMER - EXCCODE_INT_START);
132: 
133: 	return -EINVAL;
134: }
