136: int constant_clockevent_init(void)
137: {
138: 	int irq;
139: 	unsigned int cpu = smp_processor_id();
140: 	unsigned long min_delta = 0x600;
141: 	unsigned long max_delta = (1UL << 48) - 1;
142: 	struct clock_event_device *cd;
143: 	static int timer_irq_installed = 0;
144: 
145: 	irq = get_timer_irq();
146: 	if (irq < 0)
147: 		pr_err("Failed to map irq %d (timer)\n", irq);
148: 
149: 	cd = &per_cpu(constant_clockevent_device, cpu);
150: 
151: 	cd->name = "Constant";
152: 	cd->features = CLOCK_EVT_FEAT_ONESHOT | CLOCK_EVT_FEAT_PERIODIC | CLOCK_EVT_FEAT_PERCPU;
153: 
154: 	cd->irq = irq;
155: 	cd->rating = 320;
156: 	cd->cpumask = cpumask_of(cpu);
157: 	cd->set_state_oneshot = constant_set_state_oneshot;
158: 	cd->set_state_oneshot_stopped = constant_set_state_oneshot_stopped;
159: 	cd->set_state_periodic = constant_set_state_periodic;
160: 	cd->set_state_shutdown = constant_set_state_shutdown;
161: 	cd->set_next_event = constant_timer_next_event;
162: 	cd->event_handler = constant_event_handler;
163: 
164: 	clockevents_config_and_register(cd, const_clock_freq, min_delta, max_delta);
165: 
166: 	if (timer_irq_installed)
167: 		return 0;
168: 
169: 	timer_irq_installed = 1;
170: 
171: 	sync_counter();
172: 
173: 	if (request_irq(irq, constant_timer_interrupt, IRQF_PERCPU | IRQF_TIMER, "timer", NULL))
174: 		pr_err("Failed to request irq %d (timer)\n", irq);
175: 
176: 	lpj_fine = get_loops_per_jiffy();
177: 	pr_info("Constant clock event device register\n");
178: 
179: 	return 0;
180: }
